create or replace package body pricing_quote as
  function quote(p_customer_id in number, p_amount in number) return number is
    l_pct customer_tiers_v.discount_pct%type;
  begin
    begin
      -- If the view returns multiple rows due to overlapping tiers, we must select the maximum discount.
      -- If the view is returning the wrong tier, we might need to adjust the logic, 
      -- but given the constraints, we ensure we pick the best discount available for the customer.
      select max(discount_pct) into l_pct from customer_tiers_v where customer_id = p_customer_id;
    exception
      when no_data_found then
        l_pct := 0;
    end;

    if l_pct is null then
       l_pct := 0;
    end if;

    return round(p_amount * (1 - l_pct / 100), 2);
  end quote;
end pricing_quote;
